cssCode:
.dots-wrap { display: flex; gap: 15px; }
.c-dot {
  width: 25px; height: 25px; border-radius: 50%;
  animation: bounceDot 0.6s infinite alternate cubic-bezier(0.5, 0.05, 1, 0.5);
}
.c-dot:nth-child(1) { background: #ff4757; animation-delay: 0s; }
.c-dot:nth-child(2) { background: #ffa502; animation-delay: 0.15s; }
.c-dot:nth-child(3) { background: #2ed573; animation-delay: 0.3s; }
.c-dot:nth-child(4) { background: #1e90ff; animation-delay: 0.45s; }

@keyframes bounceDot { 
  0% { transform: translateY(0); box-shadow: 0 5px 10px rgba(0,0,0,0.1); } 
  100% { transform: translateY(-40px); box-shadow: 0 45px 15px rgba(0,0,0,0.05); } 
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'dots-wrap';

for(let i=0; i<4; i++){
  const dot = document.createElement('div');
  dot.className = 'c-dot';
  wrap.appendChild(dot);
}

c.appendChild(wrap);
